CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_CourseSemesterMapping_List`()
BEGIN
    SELECT
        course_semester_mapping_id,
        course_id,
        semester_id,
        status,
        created_at,
        created_by,
        updated_at,
        updated_by
    FROM course_semester_mappings
    ORDER BY course_id ASC, semester_id ASC;
END ;;
