CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_CreateStudentPromotion`(
    IN p_StudentId BIGINT,
    IN p_BranchId BIGINT,
    IN p_AcademicYearId BIGINT,
    IN p_CurrentSemester INT,
    IN p_NextSemester INT,
    IN p_EligibilityStatus VARCHAR(50),
    IN p_Remarks VARCHAR(500),
    IN p_CreatedBy BIGINT
)
BEGIN

    INSERT INTO student_promotions
    (
        StudentId,
        BranchId,
        AcademicYearId,
        CurrentSemester,
        NextSemester,
        EligibilityStatus,
        PromotionStatus,
        Remarks,
        CreatedAt,
        CreatedBy
    )
    VALUES
    (
        p_StudentId,
        p_BranchId,
        p_AcademicYearId,
        p_CurrentSemester,
        p_NextSemester,
        (p_EligibilityStatus COLLATE utf8mb4_unicode_ci),
        'Promoted',
        (p_Remarks COLLATE utf8mb4_unicode_ci),
        NOW(),
        p_CreatedBy
    );

    SELECT
        PromotionId,
        StudentId,
        BranchId,
        AcademicYearId,
        CurrentSemester,
        NextSemester,
        EligibilityStatus,
        PromotionStatus,
        Remarks,
        CreatedAt,
        CreatedBy
    FROM student_promotions
    WHERE PromotionId = LAST_INSERT_ID();

END ;;
DELIMITER ;
