DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_Department_GetById`(
    IN p_department_id BIGINT
)
BEGIN
    SELECT
        department_id,
        department_name,
        department_code,
        college_id,
        hod_user_id,
        status,
        created_at,
        created_by,
        updated_at,
        updated_by,
        deleted_at,
        deleted_by
    FROM departments
    WHERE department_id = p_department_id
      AND deleted_at IS NULL
    LIMIT 1;
END ;;
DELIMITER ;
