DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_faculty_get_by_id`(
    IN p_faculty_id BIGINT
)
BEGIN

    SELECT

        /* ============================================
           FACULTY DETAILS
           ============================================ */

        f.faculty_id AS FacultyId,

        f.faculty_code AS FacultyCode,

        f.faculty_name AS FacultyName,

        f.designation AS Designation,

        f.qualification AS Qualification,

        f.specialization AS Specialization,

        f.experience_years AS ExperienceYears,

        f.employment_type AS EmploymentType,

        f.date_of_joining AS DateOfJoining,

        f.official_email AS OfficialEmail,

        f.mobile AS Mobile,

        f.is_hod AS IsHod,

        f.status AS Status,


        /* ============================================
           USER DETAILS
           ============================================ */

        u.user_id AS UserId,

        u.employee_user_id AS EmployeeUserId,

        u.full_name AS UserFullName,

        u.email AS UserEmail,

        u.mobile AS UserMobile,


        /* ============================================
           COLLEGE DETAILS
           ============================================ */

        f.college_id AS CollegeId,

        c.college_code AS CollegeCode,

        c.college_name AS CollegeName,


        /* ============================================
           DEPARTMENT DETAILS
           ============================================ */

        f.department_id AS DepartmentId,

        d.department_code AS DepartmentCode,

        d.department_name AS DepartmentName,


        /* ============================================
           EMPLOYEE PROFILE
           ============================================ */

        f.employee_profile_id AS EmployeeProfileId,

        COALESCE(
            fp.date_of_birth,
            ep.date_of_birth
        ) AS DateOfBirth,

        COALESCE(
            fp.gender,
            ep.gender
        ) AS Gender,


        /* ============================================
           CURRENT ADDRESS
           ============================================ */

        COALESCE(
            fp.house_number,
            ep.house_number
        ) AS HouseNumber,

        COALESCE(
            fp.address,
            ep.address
        ) AS Address,

        COALESCE(
            fp.pincode,
            ep.pincode
        ) AS Pincode,

        COALESCE(
            fp.city,
            ep.city
        ) AS City,

        COALESCE(
            fp.district,
            ep.district
        ) AS District,

        COALESCE(
            fp.state,
            ep.state
        ) AS State,

        COALESCE(
            fp.country,
            'India'
        ) AS Country,


        /* ============================================
           PERMANENT ADDRESS
           ============================================ */

        COALESCE(
            fp.permanent_house_number,
            ep.permanent_house_number
        ) AS PermanentHouseNumber,

        COALESCE(
            fp.permanent_address,
            ep.permanent_address
        ) AS PermanentAddress,

        COALESCE(
            fp.permanent_pincode,
            ep.permanent_pincode
        ) AS PermanentPincode,

        COALESCE(
            fp.permanent_city,
            ep.permanent_city
        ) AS PermanentCity,

        COALESCE(
            fp.permanent_district,
            ep.permanent_district
        ) AS PermanentDistrict,

        COALESCE(
            fp.permanent_state,
            ep.permanent_state
        ) AS PermanentState,

        COALESCE(
            fp.permanent_country,
            ep.permanent_country,
            'India'
        ) AS PermanentCountry,


        /* ============================================
           PROFILE INFORMATION
           ============================================ */

        COALESCE(
            fp.about_me,
            ep.about_me
        ) AS AboutMe,

        COALESCE(
            fp.profile_image_path,
            ep.profile_image_path
        ) AS ProfileImagePath,


        /* ============================================
           EMERGENCY CONTACT
           ============================================ */

        fp.emergency_contact_name
            AS EmergencyContactName,

        fp.emergency_contact_number
            AS EmergencyContactNumber,

        fp.emergency_contact_relation
            AS EmergencyContactRelation,


        /* ============================================
           AUDIT DETAILS
           ============================================ */

        f.created_at AS CreatedAt,

        f.updated_at AS UpdatedAt


    FROM faculty f


    /* ============================================
       USER
       ============================================ */

    INNER JOIN users u
        ON u.user_id = f.user_id


    /* ============================================
       COLLEGE
       ============================================ */

    LEFT JOIN colleges c
        ON c.college_id = f.college_id


    /* ============================================
       DEPARTMENT
       ============================================ */

    LEFT JOIN departments d
        ON d.department_id = f.department_id


    /* ============================================
       EMPLOYEE PROFILE
       ============================================ */

    LEFT JOIN employee_profiles ep
        ON ep.employee_profile_id =
            f.employee_profile_id


    /* ============================================
       FACULTY PROFILE
       ============================================ */

    LEFT JOIN faculty_profile fp
        ON fp.faculty_id = f.faculty_id

        AND fp.deleted_at IS NULL


    WHERE

        f.faculty_id = p_faculty_id

        AND f.deleted_at IS NULL;


END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_faculty_get_workload` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_faculty_get_workload`(
    IN p_faculty_id BIGINT
)
BEGIN

    /* =============================================
       VALIDATE FACULTY
       ============================================= */

    IF NOT EXISTS
    (
        SELECT 1
        FROM faculty f
        WHERE f.faculty_id = p_faculty_id
          AND f.deleted_at IS NULL
    )
    THEN

        SELECT
            NULL AS FacultyId,
            NULL AS FacultyCode,
            NULL AS FacultyName,
            0 AS TotalSubjects,
            0 AS TotalSections,
            0 AS TotalPeriodsPerWeek,
            0.00 AS TotalHoursPerWeek,
            0 AS ActiveAllocations;

    ELSE

        /* =============================================
           CALCULATE FROM ACTIVE ALLOCATIONS ONLY
           ============================================= */

        SELECT

            f.faculty_id AS FacultyId,

            f.faculty_code AS FacultyCode,

            f.faculty_name AS FacultyName,


            /* =========================================
               SUBJECTS

               subject_id is currently nullable because
               Subject Master is a future module.

               Count distinct real subjects when available.
               ========================================= */

            COUNT(
                DISTINCT CASE
                    WHEN fsa.subject_id IS NOT NULL
                    THEN fsa.subject_id
                END
            ) AS TotalSubjects,


            /* =========================================
               SECTIONS
               ========================================= */

            COUNT(
                DISTINCT CASE
                    WHEN fsa.section_id IS NOT NULL
                    THEN fsa.section_id
                END
            ) AS TotalSections,


            /* =========================================
               TOTAL PERIODS

               SUM ONLY ACTIVE ALLOCATIONS
               ========================================= */

            COALESCE(
                SUM(
                    CASE
                        WHEN fsa.status = 1
                         AND fsa.deleted_at IS NULL
                        THEN fsa.periods_per_week
                        ELSE 0
                    END
                ),
                0
            ) AS TotalPeriodsPerWeek,


            /* =========================================
               TOTAL HOURS

               Current rule:
               1 Period = 1 Hour
               ========================================= */

            CAST(
                COALESCE(
                    SUM(
                        CASE
                            WHEN fsa.status = 1
                             AND fsa.deleted_at IS NULL
                            THEN fsa.periods_per_week
                            ELSE 0
                        END
                    ),
                    0
                )
                AS DECIMAL(5,2)
            ) AS TotalHoursPerWeek,


            /* =========================================
               ACTIVE ALLOCATIONS
               ========================================= */

            COUNT(
                CASE
                    WHEN fsa.status = 1
                     AND fsa.deleted_at IS NULL
                    THEN 1
                END
            ) AS ActiveAllocations


        FROM faculty f

        LEFT JOIN faculty_subject_allocations fsa
            ON fsa.faculty_id = f.faculty_id
            AND fsa.status = 1
            AND fsa.deleted_at IS NULL

        WHERE f.faculty_id = p_faculty_id
          AND f.deleted_at IS NULL

        GROUP BY

            f.faculty_id,
            f.faculty_code,
            f.faculty_name;

    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_faculty_list` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_faculty_list`(
    IN p_page_number INT,
    IN p_page_size INT,
    IN p_search VARCHAR(150),
    IN p_college_id BIGINT,
    IN p_department_id BIGINT,
    IN p_status TINYINT
)
BEGIN

    DECLARE v_offset INT DEFAULT 0;

    DECLARE v_search VARCHAR(150)
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

    /* -----------------------------
       DEFAULT PAGE
       ----------------------------- */

    IF p_page_number IS NULL OR p_page_number < 1 THEN
        SET p_page_number = 1;
    END IF;

    /* -----------------------------
       DEFAULT PAGE SIZE
       ----------------------------- */

    IF p_page_size IS NULL OR p_page_size < 1 THEN
        SET p_page_size = 20;
    END IF;

    /* Maximum 100 records */

    IF p_page_size > 100 THEN
        SET p_page_size = 100;
    END IF;

    SET v_offset =
        (p_page_number - 1) * p_page_size;

    /* -----------------------------
       NORMALIZE SEARCH VALUE
       ----------------------------- */

    SET v_search =
        CONVERT(TRIM(COALESCE(p_search, '')) USING utf8mb4);


    /* =====================================================
       FACULTY LIST
       ===================================================== */

    SELECT

        f.faculty_id AS FacultyId,
        f.user_id AS UserId,
        f.employee_profile_id AS EmployeeProfileId,
        f.college_id AS CollegeId,
        f.department_id AS DepartmentId,
        f.faculty_code AS FacultyCode,
        f.faculty_name AS FacultyName,
        f.designation AS Designation,
        f.qualification AS Qualification,
        f.specialization AS Specialization,
        f.experience_years AS ExperienceYears,
        f.employment_type AS EmploymentType,
        f.date_of_joining AS DateOfJoining,
        f.official_email AS OfficialEmail,
        f.mobile AS Mobile,
        f.is_hod AS IsHod,
        f.status AS Status,

        u.employee_user_id AS EmployeeUserId,
        u.full_name AS UserFullName,
        u.email AS UserEmail,
        u.mobile AS UserMobile,

        d.department_code AS DepartmentCode,
        d.department_name AS DepartmentName

    FROM faculty f

    LEFT JOIN users u
        ON u.user_id = f.user_id

    LEFT JOIN departments d
        ON d.department_id = f.department_id

    WHERE f.deleted_at IS NULL

    /* =====================================================
       SEARCH
       ===================================================== */

    AND
    (
        v_search = ''

        /* Faculty IDs */

        OR CAST(f.faculty_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR CAST(f.user_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR CAST(f.employee_profile_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR CAST(f.college_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR CAST(f.department_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        /* Faculty */

        OR f.faculty_code COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR f.faculty_name COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR f.designation COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR f.qualification COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        /* User */

        OR u.employee_user_id COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR u.full_name COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR u.email COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR u.mobile COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        /* Department */

        OR d.department_code COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR d.department_name COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')
    )


    /* =====================================================
       COLLEGE FILTER
       ===================================================== */

    AND
    (
        p_college_id IS NULL
        OR f.college_id = p_college_id
    )


    /* =====================================================
       DEPARTMENT FILTER
       ===================================================== */

    AND
    (
        p_department_id IS NULL
        OR f.department_id = p_department_id
    )


    /* =====================================================
       STATUS FILTER
       ===================================================== */

    AND
    (
        p_status IS NULL
        OR f.status = p_status
    )

    ORDER BY f.faculty_id DESC

    LIMIT p_page_size
    OFFSET v_offset;


    /* =====================================================
       TOTAL RECORDS
       ===================================================== */

    SELECT COUNT(*) AS TotalRecords

    FROM faculty f

    LEFT JOIN users u
        ON u.user_id = f.user_id

    LEFT JOIN departments d
        ON d.department_id = f.department_id

    WHERE f.deleted_at IS NULL

    AND
    (
        v_search = ''

        /* IDs */

        OR CAST(f.faculty_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR CAST(f.user_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR CAST(f.employee_profile_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR CAST(f.college_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR CAST(f.department_id AS CHAR)
            COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        /* Faculty */

        OR f.faculty_code COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR f.faculty_name COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR f.designation COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR f.qualification COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        /* User */

        OR u.employee_user_id COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR u.full_name COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR u.email COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR u.mobile COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        /* Department */

        OR d.department_code COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')

        OR d.department_name COLLATE utf8mb4_unicode_ci
            LIKE CONCAT('%', v_search, '%')
    )


    /* =====================================================
       COLLEGE FILTER
       ===================================================== */

    AND
    (
        p_college_id IS NULL
        OR f.college_id = p_college_id
    )


    /* =====================================================
       DEPARTMENT FILTER
       ===================================================== */

    AND
    (
        p_department_id IS NULL
        OR f.department_id = p_department_id
    )


    /* =====================================================
       STATUS FILTER
       ===================================================== */

    AND
    (
        p_status IS NULL
        OR f.status = p_status
    );

END ;;
DELIMITER ;
