CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_GetValidResetToken`(
    IN p_Token VARCHAR(255)
)
BEGIN
    SELECT
        Id,
        UserId,
        Token,
        Expiry
    FROM PasswordResetTokens
    WHERE Token = (p_Token COLLATE utf8mb4_unicode_ci)
      AND Expiry > CURRENT_TIMESTAMP
    LIMIT 1;
END ;;
