CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_active_otp`(

    IN p_identifier VARCHAR(150),

    IN p_otp_type VARCHAR(50)

)
BEGIN
 
    SELECT

        otp_verification_id,

        user_id,

        identifier,

        otp_hash,

        otp_type,

        delivery_method,

        expires_at,

        verified_at,

        attempts,

        max_attempts,

        status,

        created_at

    FROM otp_verifications

    WHERE identifier = (p_identifier COLLATE utf8mb4_unicode_ci)

      AND otp_type = (p_otp_type COLLATE utf8mb4_unicode_ci)

      AND status = 1

      AND verified_at IS NULL

      AND expires_at >= CURRENT_TIMESTAMP

    ORDER BY created_at DESC

    LIMIT 1;
 
END ;;
DELIMITER ;
