/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_Section_AssignClassTeacher`(
    IN p_section_id BIGINT,
    IN p_employee_profile_id BIGINT,
    IN p_updated_by BIGINT
)
BEGIN
    DECLARE v_college_id BIGINT;
    DECLARE v_department_id BIGINT;
    DECLARE v_academic_year_id BIGINT;
    DECLARE v_semester_id BIGINT;

    DECLARE v_employee_college_id BIGINT;
    DECLARE v_employee_department_id BIGINT;

    /* =========================================================
       1. Get active section details
       ========================================================= */

    SELECT
        college_id,
        department_id,
        academic_year_id,
        semester_id
    INTO
        v_college_id,
        v_department_id,
        v_academic_year_id,
        v_semester_id
    FROM sections
    WHERE section_id = p_section_id
      AND deleted_at IS NULL
      AND status = 1
      AND is_archived = 0
    LIMIT 1;

    IF v_college_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Active section not found.';
    END IF;


    /* =========================================================
       2. Validate active faculty
       ========================================================= */

    SELECT
        u.college_id,
        ep.department_id
    INTO
        v_employee_college_id,
        v_employee_department_id
    FROM employee_profiles ep
    INNER JOIN users u
        ON u.user_id = ep.user_id
    WHERE ep.employee_profile_id = p_employee_profile_id
      AND ep.deleted_at IS NULL
      AND ep.status = 1
      AND u.deleted_at IS NULL
      AND u.status = 1
    LIMIT 1;

    IF v_employee_college_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Active employee profile not found.';
    END IF;


    /* =========================================================
       3. Faculty College validation
       ========================================================= */

    IF v_employee_college_id <> v_college_id THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Teacher belongs to a different college.';
    END IF;


    /* =========================================================
       4. Faculty Department validation
       ========================================================= */

    IF v_employee_department_id IS NULL
       OR v_employee_department_id <> v_department_id THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Teacher belongs to a different department.';
    END IF;


    /* =========================================================
       5. Prevent duplicate faculty assignment
          Same Academic Year + Same Semester
       ========================================================= */

    IF EXISTS (
        SELECT 1
        FROM sections s
        WHERE s.class_teacher_employee_profile_id =
              p_employee_profile_id

          AND s.section_id <> p_section_id

          AND s.academic_year_id = v_academic_year_id

          AND s.semester_id = v_semester_id

          AND s.status = 1

          AND s.is_archived = 0

          AND s.deleted_at IS NULL
    ) THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Teacher is already assigned to another section for the same academic year and semester.';

    END IF;


    /* =========================================================
       6. Assign teacher
       ========================================================= */

    UPDATE sections
    SET
        class_teacher_employee_profile_id =
            p_employee_profile_id,

        updated_at = UTC_TIMESTAMP(),

        updated_by = p_updated_by

    WHERE section_id = p_section_id
      AND deleted_at IS NULL;


    /* =========================================================
       7. Return assigned teacher
       ========================================================= */

    CALL sp_Section_GetClassTeacher(p_section_id);

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_Section_AssignStudents` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
