CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_StudentAdmission_GetById`(IN p_admission_id BIGINT)
BEGIN
SELECT * FROM vw_cms_admission_directory WHERE AdmissionId=p_admission_id AND IsDeleted=0 LIMIT 1;
END ;;
