/*!50003 DROP PROCEDURE IF EXISTS `sp_student_promotion_get_failed_detained` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_student_promotion_get_failed_detained`(
    IN p_college_id BIGINT,
    IN p_academic_year_id BIGINT,
    IN p_course_id BIGINT,
    IN p_branch_id BIGINT,
    IN p_semester INT,
    IN p_search VARCHAR(150),
    IN p_outcome VARCHAR(20)
)
BEGIN

    /*
        Validate outcome
    */

    IF (p_outcome COLLATE utf8mb4_unicode_ci) NOT IN
    (
        'FAILED',
        'DETAINED'
    )
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Invalid outcome.';

    END IF;


    /*
        Validate academic year
    */

    IF NOT EXISTS
    (
        SELECT 1
        FROM academicyears ay
        WHERE ay.academic_year_id =
              p_academic_year_id

          AND ay.deleted_at IS NULL
    )
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Academic year does not exist.';

    END IF;


    /*
        Get failed / detained students
    */

    SELECT

        sp.promotion_id
            AS PromotionId,

        st.student_id
            AS StudentId,

        st.student_code
            AS StudentCode,

        st.full_name
            AS StudentName,

        st.email
            AS Email,

        st.mobile
            AS Mobile,

        st.college_id
            AS CollegeId,

        sp.from_academic_year_id
            AS AcademicYearId,

        ay.academic_year_name
            AS AcademicYearName,

        sp.from_course_id
            AS CourseId,

        c.course_code
            AS CourseCode,

        c.course_name
            AS CourseName,

        sp.from_branch_id
            AS BranchId,

        b.branch_code
            AS BranchCode,

        b.branch_name
            AS BranchName,

        sp.from_section_id
            AS SectionId,

        sec.section_name
            AS SectionName,

        sp.from_semester
            AS Semester,

        sp.attendance_percentage
            AS AttendancePercentage,

        sp.total_marks
            AS TotalMarks,

        sp.obtained_marks
            AS ObtainedMarks,

        sp.marks_percentage
            AS MarksPercentage,

        sp.passed_subjects
            AS PassedSubjects,

        sp.failed_subjects
            AS FailedSubjects,

        sp.backlog_count
            AS BacklogCount,

        sp.promotion_eligibility
            AS PromotionEligibility,

        sp.promotion_type
            AS PromotionType,

        sp.eligibility_remarks
            AS EligibilityRemarks,

        sp.remarks
            AS Remarks,

        (p_outcome COLLATE utf8mb4_unicode_ci)
            AS Outcome

    FROM student_promotions sp

    INNER JOIN students st
        ON st.student_id =
           sp.student_id

       AND st.deleted_at IS NULL

       AND st.status = 1

    INNER JOIN academicyears ay
        ON ay.academic_year_id =
           sp.from_academic_year_id

       AND ay.deleted_at IS NULL

    LEFT JOIN courses c
        ON c.course_id =
           sp.from_course_id

       AND c.deleted_at IS NULL

    LEFT JOIN branches b
        ON b.branch_id =
           sp.from_branch_id

       AND b.deleted_at IS NULL

    LEFT JOIN sections sec
        ON sec.section_id =
           sp.from_section_id

       AND sec.deleted_at IS NULL

    WHERE

        /*
            College isolation
        */

        sp.college_id =
            p_college_id

        /*
            Academic year
        */

        AND sp.from_academic_year_id =
            p_academic_year_id

        /*
            Ignore deleted promotion records
        */

        AND sp.deleted_at IS NULL

        /*
            Active promotion record
        */

        AND sp.is_active = 1

        /*
            Optional course
        */

        AND
        (
            p_course_id IS NULL

            OR sp.from_course_id =
               p_course_id
        )

        /*
            Optional branch
        */

        AND
        (
            p_branch_id IS NULL

            OR sp.from_branch_id =
               p_branch_id
        )

        /*
            Optional semester
        */

        AND
        (
            p_semester IS NULL

            OR sp.from_semester =
               p_semester
        )

        /*
            Search
        */

        AND
        (
            (p_search COLLATE utf8mb4_unicode_ci) IS NULL

            OR (p_search COLLATE utf8mb4_unicode_ci) = ''

            OR st.student_code LIKE
               CONCAT('%', (p_search COLLATE utf8mb4_unicode_ci), '%')

            OR st.full_name LIKE
               CONCAT('%', (p_search COLLATE utf8mb4_unicode_ci), '%')

            OR st.email LIKE
               CONCAT('%', (p_search COLLATE utf8mb4_unicode_ci), '%')

            OR st.mobile LIKE
               CONCAT('%', (p_search COLLATE utf8mb4_unicode_ci), '%')
        )

        /*
            FAILED
        */

        AND
        (
            (
                (p_outcome COLLATE utf8mb4_unicode_ci) = 'FAILED'

                AND
                (
                    UPPER(
                        COALESCE(
                            sp.promotion_eligibility,
                            ''
                        )
                    ) = 'FAILED'

                    OR COALESCE(
                        sp.failed_subjects,
                        0
                    ) > 0
                )
            )

            OR

            /*
                DETAINED
            */

            (
                (p_outcome COLLATE utf8mb4_unicode_ci) = 'DETAINED'

                AND
                (
                    UPPER(
                        COALESCE(
                            sp.promotion_eligibility,
                            ''
                        )
                    ) = 'DETAINED'

                    OR UPPER(
                        COALESCE(
                            sp.promotion_type,
                            ''
                        )
                    ) = 'DETAINED'
                )
            )
        )

    ORDER BY
        st.full_name ASC,
        sp.promotion_id DESC;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
